figures.script:
diagram("direction: right
[Model: vertices, faces] as m #blue
[Model → world transform] as w #violet
[View transform] as v #violet
[Clipping] as c #amber
[Projection] as p #mint
[Viewport + rasterise] as r #rose
(Pixels) as px
m -> w
w -> v
v -> c
c -> p
p -> r
r -> px
@0 m -> w : triangle
@1 w -> v : in the world
@2 v -> c : from the camera
@3 c -> p : visible part
@4 p -> r : 2-D
@5 r -> px : pixels
loop 7");
